DECLARE
BEGIN
  MERGE INTO tetools.admin_objects_config p
    USING (
      SELECT 'ALL' conf_table, 'P_DOMAIN'                      conf_name, 'p-dc.ba.uwv.nl'                                                                                                                                                                                                                                                                  conf_value FROM DUAL UNION
      SELECT 'ALL' conf_table, 'A_DOMAIN'                      conf_name, 'a-dc.ba.uwv.nl'                                                                                                                                                                                                                                                                  conf_value FROM DUAL UNION
      SELECT 'ALL' conf_table, 'T_DOMAIN'                      conf_name, 't-dc.ba.uwv.nl'                                                                                                                                                                                                                                                                  conf_value FROM DUAL UNION
      SELECT 'ALL' conf_table, 'O_DOMAIN'                      conf_name, 'o-dc.ba.uwv.nl'                                                                                                                                                                                                                                                                  conf_value FROM DUAL UNION
      SELECT 'ALL' conf_table, 'AVAILABLE_DIVISIONS'           conf_name, '{"AVAILABLE_DIVISIONS":" ALL, GEGEVENSDIENSTEN"}'                                                                                                                                                                                                                                conf_value FROM DUAL UNION
      SELECT 'ALL' conf_table, 'PREFERRED_DIVISIONS'           conf_name, 'GEGEVENSDIENSTEN'                                                                                                                                                                                                                                                                conf_value FROM DUAL UNION
      SELECT 'ALL' conf_table, 'CHECK_MD5'                     conf_name, 'NO'                                                                                                                                                                                                                                                                              conf_value FROM DUAL UNION
      SELECT 'ALL' conf_table, 'MAINTENANCE_MODE'              conf_name, 'DISABLED'                                                                                                                                                                                                                                                                        conf_value FROM DUAL UNION
      SELECT 'ALL' conf_table, 'ADMIN_MONITOR_VERSION'         conf_name, '25.0.01'                                                                                                                                                                                                                                                                         conf_value FROM DUAL UNION
      SELECT 'ALL' conf_table, 'ADMINISTRATOR_ROLE'            conf_name, 'TET_ROLE'                                                                                                                                                                                                                                                                        conf_value FROM DUAL UNION
      SELECT 'ALL' conf_table, 'CONTRIBUTOR_ROLE'              conf_name, 'POLISPLUS_FB_ROLE'                                                                                                                                                                                                                                                               conf_value FROM DUAL UNION
      SELECT 'ALL' conf_table, 'INSTALL_SCHEMA'                conf_name, 'TETOOLS'                                                                                                                                                                                                                                                                         conf_value FROM DUAL UNION
	  SELECT 'ALL' conf_table, 'EXPIRE_AFTER_DAYS'             conf_name, '7'                                                                                                                                                                                                                                                                               conf_value FROM DUAL UNION
      SELECT 'ALL' conf_table, 'GRACE_AFTER_DAYS'              conf_name, '1'                                                                                                                                                                                                                                                                               conf_value FROM DUAL UNION
      SELECT 'ALL' conf_table, 'JOB_FREQ_ARCHIVAL'             conf_name, 'YEARLY'                                                                                                                                                                                                                                                                          conf_value FROM DUAL UNION
      SELECT 'ALL' conf_table, 'JOB_FREQ_TEST_PROFILE'         conf_name, 'WEEKLY'                                                                                                                                                                                                                                                                          conf_value FROM DUAL UNION
      SELECT 'ALL' conf_table, 'AVAILABLE_ARCHIVE_FREQUENCIES' conf_name, '{"DAILY":1,"WEEKLY":7,"BIWEEKLY":14,"MONTHLY":30,"BIMONTHLY":60,"HALFYEAR":180,"YEARLY":360,"LUSTRUM":1825,"DECADE":3650}'                                                                                                                                                       conf_value FROM DUAL UNION
      SELECT 'ALL' conf_table, 'AVAILABLE_VERSION_STATUSES'    conf_name, '{"STATUSES" : [{"Name" : "RETIRED","State" : "INACTIVE"},{"Name" : "DEPRECATED","State" : "ACTIVE"},{"Name" : "CURRENT","State" : "ACTIVE"},{"Name" : "ACTIVE","State" : "ACTIVE"},{"Name" : "FUTURE RELEASE","State" : "INACTIVE"},{"Name" : "PENDING","State" : "INACTIVE"}]}' conf_value FROM DUAL UNION
	  SELECT 'ALL' conf_table, 'ARCH_FREQ_JOBS'                conf_name, 'BIMONTHLY'                                                                                                                                                                                                                                                                       conf_value FROM DUAL
      ) d
      on (p.conf_name = d.conf_name)
    WHEN MATCHED THEN
      UPDATE SET p.conf_value =
        CASE
          -- Only LOGGER_VERSION should be updated during an update
          WHEN p.conf_name = 'ADMIN_MONITOR_VERSION' THEN d.conf_value
          ELSE p.conf_value
        END
    WHEN NOT MATCHED THEN
      INSERT (p.conf_table,p.conf_name,p.conf_value)
      VALUES (d.conf_table,d.conf_name,d.conf_value);
	--
	COMMIT;
END;
/



